cloze=[
{"title":"通貨制度と産業革命","text":"1872年に定められた[[国立銀行条例]]は、1876年の改正で不換紙幣の発行を認めたため、国立銀行が急増した。西南戦争の戦費のための紙幣増発とあわせて激しい[[インフレ]]がおこった。1881年に大蔵卿となった[[松方正義]]はデフレ政策を進め、1882年に中央銀行として[[日本銀行]]を設立した。1885年には銀兌換銀行券が発行され、日本は実質的に[[銀本位制]]の国となった。物価が安定し金利が低下すると、1886〜89年に鉄道や紡績を中心とする[[企業勃興]]がおこり、産業革命が始まった。日清戦争後の1897年には[[貨幣法]]が制定され、金本位制が採用された。紡績業では、1883年に渋沢栄一らの[[大阪紡績会社]]が開業し、1897年には綿糸の輸出量が輸入量を上回ったが、原料の綿花は輸入にたよった。これに対し、国産の繭を原料とする[[製糸業]]は外貨獲得に重要な役割を果たし、手動の座繰製糸にかわって[[器械製糸]]が普及した。綿織物業では[[豊田佐吉]]らの考案した国産力織機が導入された。"},
{"title":"交通・重工業と社会問題","text":"鉄道では、1881年に設立された[[日本鉄道会社]]の成功で民営鉄道の設立ブームがおこったが、1906年の[[鉄道国有法]]で主要幹線が国有化された。政府は1884年ごろから軍事工場と鉄道を除く[[官営事業払下げ]]を進め、三井・三菱などの政商はやがて[[財閥]]へと成長した。重工業では、1897年に設立された官営の[[八幡製鉄所]]が1901年に操業を開始した。農村では小作地率が上昇し、耕作から離れて小作料収入に依存する[[寄生地主]]が増加した。工場労働者の多くは繊維産業の[[工女]]で、低賃金・長時間労働を強いられた。1897年には高野房太郎・片山潜らが[[労働組合期成会]]を結成した。栃木県では[[足尾鉱毒事件]]がおこり、衆議院議員の[[田中正造]]が被害民の救済を訴えた。政府は1900年に[[治安警察法]]で労働運動を取り締まる一方、1911年に[[工場法]]を制定した。"},
{"title":"明治の教育と文化","text":"教育では、1879年の[[教育令]]を経て、1886年に文部大臣森有礼のもとで[[学校令]]が公布された。1890年には[[教育勅語]]が発布され、翌年には[[内村鑑三]]がその勅語への拝礼をめぐって教壇を追われた。1903年には[[国定教科書]]の制度が定められた。科学では、[[北里柴三郎]]が破傷風の血清療法を確立した。文学では、[[坪内逍遙]]が『小説神髄』で写実主義をとなえ、[[二葉亭四迷]]が言文一致体で『浮雲』を書いた。日清戦争前後には[[ロマン主義]]がさかんになり、[[樋口一葉]]は『たけくらべ』を著した。日露戦争前後には[[自然主義]]が主流となった。美術では、アメリカ人[[フェノロサ]]と岡倉天心の影響で1887年に[[東京美術学校]]が設立された。西洋画では、フランスで学んだ[[黒田清輝]]が白馬会を創立した。1907年には[[文展]]が開設され、伝統美術と西洋美術が共通の発表の場をもった。"}]
ans=[]
for c in cloze: ans+=re.findall(r'\[\[([^\]]+)\]\]',c['text'])
pl=''.join(re.sub(r'\[\[[^\]]+\]\]','□',c['text']) for c in cloze)
print('cloze',len(ans),'dup',[a for a in set(ans) if ans.count(a)>1],'leak',[a for a in set(ans) if a in pl],'overlap',[(a,b) for a in set(ans) for b in set(ans) if a!=b and a in b])
notin=[a for a in ans if not any(a in t for t in txt.values())]; print('cloze-not-in-lessons',notin)

pack={"id":"sangyo","title":"近代（産業革命と明治の文化）","subtitle":"松方財政・紡績と製糸・財閥・寄生地主制・労働問題・明治の教育と文化","order":4.3,
"range":"近代産業の発展と近代文化の発達 ── 松方財政から産業革命・社会問題、明治の教育・文学・美術まで（教科書 p.279〜294）",
"timeline":timeline,"lessons":lessons,"quiz":quiz,"terms":terms,"goro":goro,"ronjutsu":ronj,"cloze":cloze,"figures":figures}
s=open(src,encoding='utf-8').read()
m=re.search(r'const DEFAULT_PACKS = (\[[\s\S]*?\n\]);',s); packs=json.loads(m.group(1))
packs=[p for p in packs if p['id']!='sangyo']
i=[k for k,p in enumerate(packs) if p['id']=='nichiro'][0]; packs.insert(i+1,pack)
